{
    if (!g || drive < 0 || drive >= N_DRIVE) {
        return -EINVAL;
    }

    if (type != -1) {
        if (!capable(CAP_SYS_ADMIN)) {
            return -EPERM;
        }

        /* Update floppy type and sizes based on the specified type */
        if (type >= N_FLOPPY_TYPE) {
            return -EINVAL;
        }

        FLOPPY_DRIVE(drive).root_dir = type;
        FLOPPY_DRIVE(drive).block_size = g->size;
        FLOPPY_DRIVE(drive).capacity = g->capacity;
    } else {
        /* Handle disk changes and update user parameters */
        if (g->track > g->tracks) {
            return -EINVAL;
        }

        /* Update user parameters and manage buffer cache */
        FLOPPY_DRIVE(drive).current_track = g->track;
        FLOPPY_DRIVE(drive).head = g->head;
    }

    /* Invalidate the buffer cache and maintain drive state consistency */
    invalidate floppy_cache(drive);

    return 0;
}

