#include <linux/fd.h>
#include <linux/fs.h>
#include <linux/uaccess.h>

int floppy_set_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev)
{
    if (!g)
        return -EINVAL;

    if (type != -1) {
        if (!capable(CAP_SYS_ADMIN))
            return -EPERM;

        if (g->nr_cylinders > MAX_CMDS || g->nr_tracks > MAX_TRACKS ||
            g->nr_sectors > MAX_SECTORS || g->sect_size > MAX_SECTOR_SIZE)
            return -EINVAL;

        current_floppy()->fmt_gap = g->fmt_gap;
        current_floppy()->fmt_fill = g->fmt_fill;
        current_floppy()->fmt_nsec = g->nr_sectors;
        current_floppy()->fmt_precomp = g->precomp;
        current_floppy()->fmt_offset[0] = g->track_size[0];
        current_floppy()->fmt_offset[1] = g->track_size[1];
        current_floppy()->fmt_offset[2] = g->track_size[2];
        current_floppy()->fmt_offset[3] = g->track_size[3];
        current_floppy()->type = type;
        set_capacity(bdev->bd_disk, (sector_t)g->size);
    } else {
        struct floppy_struct *old = current_floppy();

        if (g->size != -1 && old->size != g->size)
            invalidate_partition(bdev, 1);

        if (g->nr_cylinders != -1)
            old->nr_cylinders = g->nr_cylinders;
        if (g->nr_tracks != -1)
            old->nr_tracks = g->nr_tracks;
        if (g->nr_sectors != -1)
            old->nr_sectors = g->nr_sectors;
        if (g->sect_size != -1)
            old->sect_size = g->sect_size;
        if (g->track_size[0] != -1)
            old->track_size[0] = g->track_size[0];
        if (g->track_size[1] != -1)
            old->track_size[1] = g->track_size[1];
        if (g->track_size[2] != -1)
            old->track_size[2] = g->track_size[2];
        if (g->track_size[3] != -1)
            old->track_size[3] = g->track_size[3];
        if (g->fmt_gap != -1)
            old->fmt_gap = g->fmt_gap;
        if (g->fmt_fill != -1)
            old->fmt_fill = g->fmt_fill;
        if (g->precomp != -1)
            old->precomp = g->precomp;
    }

    return 0;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    if (!g || drive < 0 || drive >= N_DRIVE || (!type && !g->size)) {
        return -EINVAL;
    }

    if (type) {
        if (!capable(CAP_SYS_ADMIN)) {
            return -EPERM;
        }

        if (type >= N_SUPPORTED_TYPES) {
            return -EINVAL;
        }

        /* Update the drive's floppy type */
        unit[drive].type = type;
        unit[drive].size = g->size;
        unit[drive].capacity = g->capacity;
        unit[drive].fmt_gap = g->fmt_gap;
        unit[drive].fmt_gap2 = g->fmt_gap2;
    } else {
        if (g->size == 0) {
            return -EINVAL;
        }

        if (check_disk_change(drive)) {
            return -ENOMEDIUM;
        }

        /* Update user-defined parameters and manage buffer cache */
        memcpy(&user_params[drive], g, sizeof(struct floppy_struct));
        invalidate_floppy_cache(drive);
    }

    return 0;
}

